use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut cap = 1
    let mut first = true
    let mut ks: Vec<int> = []
    let mut vs: Vec<int> = []
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 { continue }
        if first {
            cap = parts[0].parse::<int>().unwrap_or(1)
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let v = parts[2].parse::<int>().unwrap_or(0)
            let mut nk: Vec<int> = [k]
            let mut nv: Vec<int> = [v]
            let mut i = 0
            while i < ks.len() {
                if ks[i] != k {
                    nk.push(ks[i])
                    nv.push(vs[i])
                }
                i += 1
            }
            if nk.len() as int > cap {
                println("evict ${nk[nk.len() - 1]}")
                nk.pop()
                nv.pop()
            }
            ks = nk
            vs = nv
        } else if cmd == "get" {
            let k = parts[1].parse::<int>().unwrap_or(0)
            let mut found = -1
            let mut nk: Vec<int> = []
            let mut nv: Vec<int> = []
            let mut i = 0
            while i < ks.len() {
                if ks[i] == k {
                    found = vs[i]
                }
                i += 1
            }
            let mut present = false
            for x in ks {
                if x == k { present = true }
            }
            if present {
                nk.push(k)
                nv.push(found)
                i = 0
                while i < ks.len() {
                    if ks[i] != k {
                        nk.push(ks[i])
                        nv.push(vs[i])
                    }
                    i += 1
                }
                ks = nk
                vs = nv
            }
            println("${found}")
        } else if cmd == "keys" {
            if ks.len() == 0 {
                println("<empty>")
            } else {
                let mut out = ""
                let mut i = 0
                while i < ks.len() {
                    if i > 0 { out = out + " " }
                    out = out + "${ks[i]}"
                    i += 1
                }
                println("${out}")
            }
        }
    }
}

